import { routeAgentRequest } from "agents";
import { MicrocloudAgentDO } from "./agent";
import legacy from "./index.legacy";

export { MicrocloudAgentDO };

export default {
  async fetch(
    request: Request,
    env: Env,
    ctx: ExecutionContext,
  ): Promise<Response> {
    /*
     * Real Cloudflare Agents routing.
     *
     * /agents/microcloud-agent-do/:instance
     *
     * Agent requests are handled by the Durable Object.
     */
    const agentResponse = await routeAgentRequest(request, env);

    if (agentResponse) {
      return agentResponse;
    }

    /*
     * Browser API compatibility route.
     *
     * This does NOT implement a second browser runtime.
     * It forwards /api/browser directly to the existing real
     * /browser/run implementation in src/index.legacy.ts.
     */
    if (request.method === "POST" && new URL(request.url).pathname === "/api/browser") {
      const target = new URL("/browser/run", request.url);

      const browserRequest = new Request(target.toString(), {
        method: "POST",
        headers: request.headers,
        body: await request.text(),
      });

      return legacy.fetch(browserRequest, env);
    }

    /*
     * Existing DOLOR3V Worker routes remain intact:
     *
     * /ai/text
     * /ai/image
     * /ai/build
     * /browser/run
     * /webmcp
     */
    return legacy.fetch(request, env);
  },
} satisfies ExportedHandler<Env>;
