export async function generatePollinationsText(prompt: string): Promise<string> {
  const response = await fetch(`https://text.pollinations.ai/${encodeURIComponent(prompt)}?model=openai&seed=42`, {
    headers: { "User-Agent": "DOLOR3V-Microcloud/1.0" }
  });
  if (!response.ok) throw new Error(`Pollinations Text API error: ${response.status}`);
  return await response.text();
}

export function buildPollinationsImageUrl(prompt: string, width = 800, height = 600): string {
  const cleanPrompt = encodeURIComponent(prompt.trim());
  return `https://gen.pollinations.ai/prompt/${cleanPrompt}?width=${width}&height=${height}&seed=${Math.floor(Math.random() * 1000000)}&nologo=true`;
}
