import {
  Agent,
  type Connection,
  type ConnectionContext,
  type WSMessage,
} from "agents";

import {
  dispatchAHP,
} from "./ahp/dispatch";

import {
  AHP_PROTOCOL_VERSION,
  error,
  protocolInfo,
} from "./ahp/protocol";

import {
  INITIAL_AGENT_STATE,
  type MicrocloudAgentState,
} from "./agent-state";

export class MicrocloudAgentDO extends Agent<Env, MicrocloudAgentState> {
  initialState: MicrocloudAgentState = {
    ...INITIAL_AGENT_STATE,
    updatedAt: Date.now(),
  };

  async onStart() {
    if (!this.state.protocolVersion) {
      this.setState({
        ...INITIAL_AGENT_STATE,
        updatedAt: Date.now(),
      });
    }
  }

  async onRequest(request: Request): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname.endsWith("/health")) {
      return Response.json({
        ok: true,
        service: "dolor3v-microcloud-agent",
        agent: "MicrocloudAgentDO",
        protocol: AHP_PROTOCOL_VERSION,
        instance: this.name,
        state: this.state.status,
        timestamp: Date.now(),
      });
    }

    if (url.pathname.endsWith("/state")) {
      return Response.json({
        ok: true,
        state: this.state,
      });
    }

    if (
      url.pathname.endsWith("/ahp") &&
      request.method === "POST"
    ) {
      let body: unknown;

      try {
        body = await request.json();
      } catch {
        return Response.json(
          error(null, -32700, "Invalid JSON"),
          { status: 400 },
        );
      }

      const result = await dispatchAHP(this, body);

      return Response.json(result, {
        headers: {
          "Cache-Control": "no-store",
        },
      });
    }

    if (url.pathname.endsWith("/protocol")) {
      return Response.json(protocolInfo());
    }

    return Response.json({
      ok: true,
      service: "dolor3v-microcloud-agent",
      endpoints: [
        "/health",
        "/state",
        "/protocol",
        "/ahp",
      ],
    });
  }

  async onConnect(
    connection: Connection,
    _ctx: ConnectionContext,
  ) {
    connection.send(
      JSON.stringify({
        type: "microcloud.connected",
        agent: "MicrocloudAgentDO",
        protocol: AHP_PROTOCOL_VERSION,
        connectionId: connection.id,
        timestamp: Date.now(),
      }),
    );
  }

  async onMessage(
    connection: Connection,
    message: WSMessage,
  ) {
    if (typeof message !== "string") {
      connection.send(
        JSON.stringify(
          error(null, -32600, "Binary messages are not supported"),
        ),
      );
      return;
    }

    let payload: unknown;

    try {
      payload = JSON.parse(message);
    } catch {
      connection.send(
        JSON.stringify(
          error(null, -32700, "Invalid JSON"),
        ),
      );
      return;
    }

    const result = await dispatchAHP(this, payload);

    connection.send(JSON.stringify(result));

    this.broadcast(
      JSON.stringify({
        type: "microcloud.state",
        state: this.state,
        timestamp: Date.now(),
      }),
      [connection.id],
    );
  }

  async onClose() {
    // Cloudflare Agents manages connection lifecycle.
  }
}
